/* RDT-02: navegação e registros locais. Nenhum comando Windows é executado. */
(()=>{'use strict';
const catalog=window.HUB_CATALOG,C=window.HubCore,KEY='rdt02-state-v1',main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.empty(),storageError=false,current=null;
try{const saved=localStorage.getItem(KEY);if(saved)state=C.validate(JSON.parse(saved));}catch{storageError=true;}
const aiServices=[['ChatGPT','https://chatgpt.com/'],['Claude','https://claude.ai/'],['Gemini','https://gemini.google.com/'],['Grok','https://grok.com/'],['Copilot','https://copilot.microsoft.com/'],['Perplexity','https://www.perplexity.ai/']];
function aiPanel(){return `<section class="panel ai-panel" aria-labelledby="ai-heading"><div class="eyebrow">Ferramentas para esta atividade</div><h2 id="ai-heading">Inteligência artificial</h2><div class="ai-links">${aiServices.map(([name,url])=>`<a class="ai-link" href="${url}" target="_blank" rel="noopener noreferrer">${name}<span aria-hidden="true">↗</span></a>`).join('')}</div><p class="hint">Abra a IA de sua preferência e escolha o modelo dentro do serviço. Os links abrem em uma nova aba; o contexto desta atividade não é enviado automaticamente.</p></section>`;}
const category=id=>catalog.categories.find(c=>c.id===id);
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;return true;}catch{storageError=true;toast('Não foi possível salvar. Exporte um backup antes de sair.');return false;}}
function nav(active){document.getElementById('nav').innerHTML=`<a class="nav-link ${active==='inicio'?'active':''}" href="#inicio">⌂ <span>Visão geral</span></a><a class="nav-link ${active==='favoritos'?'active':''}" href="#favoritos">☆ <span>Favoritos</span><span class="nav-count">${state.favorites.length}</span></a><div class="nav-heading">Atividades</div>`+catalog.categories.map(c=>`<a class="nav-link ${active===c.id?'active':''}" ${active===c.id?'aria-current="page"':''} href="#categoria/${c.id}"><span class="nav-number">${c.number}</span><span>${esc(c.name)}</span><span class="nav-count">${catalog.activities.filter(a=>a.category===c.id).length}</span></a>`).join('');}
function row(a){return `<a class="activity-row" href="#atividade/${a.id}"><div><span class="code">${esc(a.code)}</span><strong>${esc(a.title)}</strong><small>${esc(category(a.category).name)}</small></div><span class="badge">${a.pilot?'Piloto':'Acervo importado'}</span></a>`;}
function pilot(a){const r=state.records[a.id];return `<a class="pilot-card" href="#atividade/${a.id}"><div class="pilot-body"><span class="code">${esc(a.code)} · PILOTO</span><h3>${esc(a.title)}</h3><p>${esc(r?.next|| (a.id==='af-01-ib6'?'Fontes, perguntas e ambiente de análise.':'Leitura, exercícios e suas próximas perguntas.'))}</p><span class="cta">${r?'Continuar atividade':'Abrir atividade'} ↗</span></div><img src="${a.image}" alt="" loading="lazy"></a>`;}
function home(){nav('inicio');main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">Seu ponto de partida</div><h1>O que vamos continuar?</h1><p class="subtitle">Materiais, ferramentas e contexto, reunidos por atividade.</p></div><span class="badge">${catalog.activities.length} atividades</span></div><div class="pilot-grid">${catalog.activities.filter(a=>a.pilot).map(pilot).join('')}</div><div class="section-head"><h2>Todos os seus espaços</h2><small>${catalog.categories.length} categorias</small></div><div class="search-wrap"><input id="search" aria-label="Buscar em todas as atividades" type="search" placeholder="Buscar atividade, livro ou referência…"></div><div id="results" class="category-grid">${catalog.categories.map(c=>`<a class="category-card" href="#categoria/${c.id}"><span class="num">${c.number}</span><span><strong>${esc(c.name)}</strong><small>${catalog.activities.filter(a=>a.category===c.id).length} atividades</small></span></a>`).join('')}</div>`;const initial=document.getElementById('results').innerHTML;document.getElementById('search').oninput=e=>{const q=e.target.value.trim().toLocaleLowerCase('pt-BR');const box=document.getElementById('results');box.className=q?'activity-list':'category-grid';box.innerHTML=q?(catalog.activities.filter(a=>`${a.title} ${a.code} ${category(a.category).name}`.toLocaleLowerCase('pt-BR').includes(q)).map(row).join('')||'<div class="empty">Nenhuma atividade encontrada.</div>'):initial;};}
function list(id){const favorite=id==='favoritos',cat=category(id);nav(id);const entries=catalog.activities.filter(a=>favorite?state.favorites.includes(a.id):a.category===id);main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">${favorite?'Seus acessos':'Categoria '+esc(cat?.number||'')}</div><h1>${esc(favorite?'Favoritos':cat?.name||'Categoria não encontrada')}</h1><p class="subtitle">${entries.length} atividades${favorite?' selecionadas por você.':' · referências preservadas do RDT-00.'}</p></div></div><div class="search-wrap"><input type="search" id="search" aria-label="Filtrar atividades" placeholder="Filtrar nesta lista…"></div><div id="results" class="activity-list">${entries.map(row).join('')||`<div class="empty">${favorite?'Marque a estrela dentro de uma atividade para encontrá-la aqui.':'Este espaço está reservado. Ainda não há atividades importadas nesta categoria.'}</div>`}</div>`;document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('results').innerHTML=entries.filter(a=>(a.title+' '+a.code).toLowerCase().includes(q)).map(row).join('')||'<div class="empty">Nenhuma atividade encontrada.</div>';};}
function resource(r,custom=false){if(!C.validUrl(r.url))return '';return `<div class="resource"><span class="resource-icon">${r.kind==='legacy'||r.kind==='ia'?'✦':'↗'}</span><div class="resource-copy"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a><small>${esc(r.detail||new URL(r.url).hostname)}</small></div>${custom?`<button class="button small remove-resource" data-id="${esc(r.id)}" aria-label="Remover ${esc(r.title)}">×</button>`:''}</div>`;}
function detail(a){if(!a){main.innerHTML='<div class="empty">Atividade não encontrada. <a href="#inicio">Voltar ao início</a></div>';nav('');return;}current=a;nav(a.category);document.getElementById('crumb').textContent=category(a.category).name+' / '+a.code;document.title=a.title+' · RDT-02';const r=state.records[a.id]||{},isBook=a.id==='emt-01-es';main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">${esc(a.code)}${a.pilot?' · PILOTO':''}</div><h1>${esc(a.title)}</h1>${a.subtitle?`<p class="subtitle">${esc(a.subtitle)}</p>`:''}<p class="subtitle">${esc(a.description||'Recursos importados. Use este espaço para registrar o contexto da atividade.')}</p></div><button id="favorite" class="button" aria-pressed="${state.favorites.includes(a.id)}">${state.favorites.includes(a.id)?'★ Favorito':'☆ Favoritar'}</button></div>${aiPanel()}<div class="detail-grid"><div class="stack"><section class="panel resume-panel"><div class="section-head"><h2>${isBook?'Continuar estudo':'Continuar de onde parei'}</h2><span class="badge">Neste aparelho</span></div><form id="recordForm"><div class="field-grid"><label>${isBook?'Capítulo / seção / posição online':'Arquivo, função ou assunto'}<input name="position" value="${esc(r.position)}" placeholder="${isBook?'Ex.: capítulo 2, seção 2.1':'Ex.: módulo ou função em análise'}"></label><label>${isBook?'Página do PDF':'Versão / commit / referência'}<input name="pdfPage" value="${esc(r.pdfPage)}" placeholder="${isBook?'Separada da posição online':'Referência exata do código'}"></label></div><label>Pergunta em andamento<textarea name="question" placeholder="O que você quer compreender?">${esc(r.question)}</textarea></label><label>Próximo passo<textarea name="next" placeholder="Uma indicação curta para retomar depois.">${esc(r.next)}</textarea></label><label>Anotações e conclusões<textarea name="notes" class="notes" placeholder="Registre explicações, descobertas ou exercícios. Texto simples; você também pode escrever Markdown.">${esc(r.notes)}</textarea></label><div class="save-status" id="saveStatus">${r.updatedAt?'Último registro: '+esc(new Date(r.updatedAt).toLocaleString('pt-BR')):'As alterações são salvas automaticamente neste navegador.'}</div></form>${a.historical?`<p class="notice">${esc(a.historical)}</p>`:''}</section><section class="panel"><div class="section-head"><h2>Materiais e recursos</h2><button id="addResource" class="button small">+ Adicionar</button></div>${a.resources.filter(r=>r.kind!=='legacy').map(r=>resource(r)).join('')}${(state.custom[a.id]||[]).map(r=>resource(r,true)).join('')}${!a.resources.some(r=>r.kind!=='legacy')&&!(state.custom[a.id]||[]).length?'<p class="hint">Adicione referências, anotações externas e ferramentas para esta atividade.</p>':''}</section></div><div class="stack">${a.environment?`<section class="panel"><div class="eyebrow">Ambiente de trabalho</div><h2>InterBase na sua VM</h2><p class="env-title">${esc(a.environment.name)}</p><p class="hint">${esc(a.environment.host)}<br>${esc(a.environment.access)}</p><div class="notice">Integração Windows pendente. O hub ainda não inicia, desliga ou consulta o estado desta VM.</div><p class="hint">${esc(a.environment.note)}</p></section>`:''}${a.localFile?`<section class="panel"><div class="eyebrow">Seu material local</div><h2>PDF no computador</h2><p class="path">${esc(a.localFile)}</p><button id="copyPath" class="button small">Copiar caminho</button><p class="hint">Caminho preservado do Automation. A abertura pelo hub depende de uma integração local.</p></section>`:''}<section class="panel"><h2>Levar este registro</h2><p class="hint">Ainda não há sincronização automática entre aparelhos. Exporte um backup antes de trocar de navegador ou limpar seus dados.</p><div class="data-actions"><button id="exportNote" class="button small">Baixar anotação .md</button><a class="button small" href="#dados">Backup completo</a></div><p class="hint">Origem: ${esc(a.source)}</p></section></div></div>`;
document.getElementById('favorite').onclick=()=>{state.favorites=state.favorites.includes(a.id)?state.favorites.filter(id=>id!==a.id):[...state.favorites,a.id];persist();detail(a);};
document.getElementById('recordForm').oninput=e=>{if(!['position','pdfPage','question','next','notes'].includes(e.target.name))return;state.records[a.id]={...(state.records[a.id]||{}),[e.target.name]:e.target.value,updatedAt:new Date().toISOString()};const ok=persist();document.getElementById('saveStatus').textContent=ok?'Salvo neste navegador · '+new Date().toLocaleTimeString('pt-BR'):'Falha ao salvar. Exporte seus registros antes de sair.';};
document.getElementById('recordForm').onsubmit=e=>e.preventDefault();document.getElementById('addResource').onclick=()=>document.getElementById('resourceDialog').showModal();
document.querySelectorAll('.remove-resource').forEach(b=>b.onclick=()=>{if(!confirm('Remover este recurso adicionado por você?'))return;state.custom[a.id]=state.custom[a.id].filter(r=>r.id!==b.dataset.id);persist();detail(a);});
document.getElementById('copyPath')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(a.localFile);toast('Caminho copiado.');}catch{toast('Selecione e copie o caminho exibido acima.');}});
document.getElementById('exportNote').onclick=()=>{const v=state.records[a.id]||{};download(a.id+'.md',`# ${a.title}\n\nCódigo: ${a.code}\n\n## Posição\n${v.position||''}\n\n## ${isBook?'Página PDF':'Versão / referência'}\n${v.pdfPage||''}\n\n## Pergunta\n${v.question||''}\n\n## Próximo passo\n${v.next||''}\n\n## Anotações\n${v.notes||''}\n`,'text/markdown');};}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function dataPage(){nav('dados');main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">Seus registros</div><h1>Backup e meus dados</h1><p class="subtitle">Uma cópia que você pode guardar e levar para outro aparelho.</p></div></div><section class="panel"><h2>Armazenamento neste navegador</h2><p>Este piloto salva anotações, favoritos e recursos adicionados apenas neste navegador. Os outros aparelhos não recebem as alterações automaticamente.</p><div class="notice">Importar substitui os registros locais pelo backup escolhido. Exporte primeiro se quiser preservar as alterações deste aparelho.</div><p>${Object.keys(state.records).length} atividades com registros · ${state.favorites.length} favoritos</p><div class="data-actions"><button id="exportData" class="button primary">Exportar backup</button><button id="importData" class="button">Importar backup</button></div><input class="file-input" type="file" id="backupFile" accept="application/json,.json"><p class="hint">O backup inclui registros pessoais, favoritos e recursos adicionados. O acervo original continua nos arquivos do projeto.</p></section>`;document.getElementById('exportData').onclick=()=>download('rdt02-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');document.getElementById('importData').onclick=()=>document.getElementById('backupFile').click();document.getElementById('backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Arquivo muito grande. Limite: 10 MB.');const parsed=C.validate(JSON.parse(await file.text()));if(!confirm('Substituir os registros deste navegador pelo backup?'))return;state=parsed;persist();dataPage();toast(storageError?'Importado em memória, mas não foi possível salvar.':'Backup importado.');}catch(err){toast(err.message||'Não foi possível importar.');}};}
function render(){current=null;document.title='RDT · Meu espaço de trabalho';document.getElementById('crumb').textContent='Meu espaço';const [page,id]=location.hash.slice(1).split('/');document.body.classList.remove('menu-open');document.getElementById('menu').setAttribute('aria-expanded','false');if(page==='atividade')detail(catalog.activities.find(a=>a.id===id));else if(page==='categoria')list(id);else if(page==='favoritos')list('favoritos');else if(page==='dados')dataPage();else home();window.scrollTo(0,0);if(storageError)toast('Os dados locais não puderam ser lidos ou salvos. Preserve seu backup.');}
document.getElementById('resourceForm').onsubmit=e=>{e.preventDefault();if(!current)return;const data=new FormData(e.target),url=String(data.get('url')).trim(),title=String(data.get('title')).trim();if(!C.validUrl(url)||!title){toast('Informe um nome e um endereço http ou https válido.');return;}state.custom[current.id]??=[];state.custom[current.id].push({id:'r-'+Date.now(),title,url,kind:data.get('kind')});persist();document.getElementById('resourceDialog').close();e.target.reset();detail(current);};
document.getElementById('cancelResource').onclick=()=>document.getElementById('resourceDialog').close();document.getElementById('menu').onclick=()=>{document.body.classList.toggle('menu-open');document.getElementById('menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));};document.getElementById('closeMenu').onclick=()=>{document.body.classList.remove('menu-open');document.getElementById('menu').setAttribute('aria-expanded','false');document.getElementById('menu').focus();};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');document.getElementById('menu').setAttribute('aria-expanded','false');}});window.addEventListener('hashchange',render);render();
})();
